import{z as o,x as p,o as l,c as B,q as t,j as r,D as e,d as n,s as i,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"哈希与碰撞","description":"","frontmatter":{"title":"哈希与碰撞","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hash-collision.md","filePath":"cs/hash-collision.md","lastUpdated":1791063341000}'),d={name:"cs/hash-collision.md"};function m(h,a,D,u,f,C){const s=p("Mermaid");return l(),B("div",null,[a[2]||(a[2]=t('<h1 id="哈希与碰撞" tabindex="-1">哈希与碰撞 <a class="header-anchor" href="#哈希与碰撞" aria-label="Permalink to &quot;哈希与碰撞&quot;">​</a></h1><div class="epigraph"><p>压缩任意长输入到固定摘要；有用的是碰撞难找，不是「摘要看起来随机」这一句。</p><footer>—— 据 Damgård 对哈希设计；Stallings 对原像与碰撞的整理</footer></div><p><a href="/cs/dh-vs-rsa">上一课</a>用公钥运会话键。本课不重做 DH。缺口是：签名、MAC、口令存储、承诺都要把「大消息」收成固定串，并希望找不到两个输入同一摘要。<a href="/cs/hash-function">数据结构</a>的散列要快、要均匀；本课的密码学哈希还要<strong>原像难、第二原像难、碰撞难</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>索引哈希可以故意设计成简单取模。若敌手能找到 \\(x\\neq y\\)、\\(H(x)=H(y)\\)，签名可被挪到另一份文件上，第二原像则让给定消息被顶替。缺口不是再讲链地址，而是这三条性质的强弱：碰撞最容易（生日界），原像最难。MD5、SHA-1 的碰撞已在密码分析里垮掉，主干用它们当反例，不用当机制。</p><p><span class="marginnote">生日界：约 \\(2^{n/2}\\) 次评估可望找到碰撞。\\(n=256\\) 时该数仍大；\\(n=128\\) 的碰撞安全边际按今天的标准不够当签名哈希。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>密码学哈希：公开、确定性、固定输出。Merkle–Damgård 把压缩函数迭代；海绵结构（SHA-3）是另一族。本课不证随机预言机，只要求后课把 \\(H\\) 当「除穷举与生日外不会被操纵」的零件——并且知道现实哈希会破，要能换。</p><p><span class="marginnote">直觉类比：生日悖论——23 人的班里「有人同一天生日」的概率已过半。找碰撞同理：不是找指定摘要的原像，而是攒一堆输入等任意两条撞车，攒到约 \\(2^{n/2}\\) 条时希望就过半。这就是 \\(n=128\\) 的摘要不够当签名哈希的算术根源。</span></p><p><span class="marginnote">数字实例：\\(2^{256}\\approx 1.2\\times 10^{77}\\)，比可观测宇宙的原子总数（约 \\(10^{80}\\)）只小三个数量级。所以对 SHA-256 谈「穷举原像」不是算力工程问题，而是物理问题；真正要防的是结构缺陷与生日界。</span></p>',10)),(l(),r(A,null,{default:e(()=>[i(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MSG%5B%22%E4%BB%BB%E6%84%8F%E9%95%BF%E6%B6%88%E6%81%AF%22%5D%20--%3E%20H%5B%22H%3A%20%E6%8A%97%E7%A2%B0%E6%92%9E%E6%91%98%E8%A6%81%22%5D%0A%20%20H%20--%3E%20MAC%5B%22%E5%90%8E%E8%AF%BE%3A%20MAC%20%E4%B8%8E%E7%AD%BE%E5%90%8D%22%5D%0A%20%20H%20--%3E%20PWD%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%8F%A3%E4%BB%A4%E5%8A%A0%E7%9B%90%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"签名对摘要签，不对流式明文逐比特做昂贵公钥运算。完整性可以先哈希再加密，但正确组合仍是 AEAD 或 Encrypt-then-MAC。口令存哈希而不是明文，下一课还要加盐与慢哈希，本课只把「单向压缩」交出去。",-1)),a[5]||(a[5]=E("p",null,"长度扩展：某些 MD 构造下，知道 \\(H(m)\\) 可伪造 \\(H(m\\|pad\\|\\mathit{suffix})\\) 而不知 \\(m\\)。这是后课 MAC 不用「裸哈希当认证」的原因之一。",-1)),a[6]||(a[6]=E("p",null,"第二原像难于碰撞：给定 \\(m\\) 再找 \\(m'\\) 比随便找一对更难，签名要的是这一层。",-1)),a[7]||(a[7]=E("p",null,"三种攻击各自要做什么、难度差在哪：",-1)),(l(),r(A,null,{default:e(()=>[i(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20AT%5B%22%E6%95%8C%E6%89%8B%E8%83%BD%E5%81%9A%E4%BB%80%E4%B9%88%22%5D%20--%3E%20P1%5B%22%E5%8E%9F%E5%83%8F%3A%20%E7%BB%99%E6%91%98%E8%A6%81%20y%20%E5%8F%8D%E6%89%BE%20x%22%5D%0A%20%20AT%20--%3E%20P2%5B%22%E7%AC%AC%E4%BA%8C%E5%8E%9F%E5%83%8F%3A%20%E7%BB%99%E5%AE%9A%20m%20%E6%89%BE%20m'%20%E5%90%8C%E6%91%98%E8%A6%81%22%5D%0A%20%20AT%20--%3E%20P3%5B%22%E7%A2%B0%E6%92%9E%3A%20%E8%87%AA%E7%94%B1%E6%89%BE%E4%BB%BB%E6%84%8F%E4%B8%80%E5%AF%B9%20x%2Cy%22%5D%0A%20%20P1%20--%3E%20D1%5B%22%E7%BA%A6%202%5En%20%E6%AC%A1%E5%B0%9D%E8%AF%95%22%5D%0A%20%20P2%20--%3E%20D2%5B%22%E7%BA%A6%202%5En%20%E6%AC%A1%E5%B0%9D%E8%AF%95%22%5D%0A%20%20P3%20--%3E%20D3%5B%22%E7%BA%A6%202%5E(n%2F2)%3A%20%E7%94%9F%E6%97%A5%E7%95%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=t('<p><span class="marginnote">为什么重要：挪用签名通常走碰撞这条路，成本约 \\(2^{n/2}\\)，比反推原文便宜得多。MD5 被现实攻击垮掉正是「造出一对同摘要文件」：先造两份内容不同、摘要相同的合同，让你签 A，再把签名贴到 B 上——全程不需要你的私钥。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把哈希当加密：摘要不是密文，通常可公开。也不要把「区块链」插入本栏。校验和、CRC 防随机噪声，不防敌手，那是<a href="/cs/error-correcting-intuition">纠错码</a>的亲戚，不是本课。</p><p>文件完整性可以公开贴 \\(H(m)\\)，前提是获取摘要的通道本身完整；否则敌手同时换文件与摘要。后课默认：谈到摘要，默认抗碰撞密码学哈希；认证要 MAC 或签名，不是把 \\(H\\) 公开贴上去。</p><p>换哈希算法是协议版本问题。主干只要求：摘要是可替换零件，破掉的函数退出实现，不改 MAC/签名的接口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>长度扩展说明裸哈希不当 MAC；下一课 HMAC 与签名分开这层误用。</p></li><li><p>破掉的 MD5/SHA-1 当反例，不当现行机制。</p></li><li><p>公钥信封已在；本课交出抗碰撞摘要，并分清原像与碰撞。</p></li><li><p>生日界决定摘要长度；破掉的算法当反例。</p></li><li><p>用摘要做认证与不可否认，是 MAC 与签名课。</p></li><li><p>出处：Damgård；Stallings；对照 SHA-2/SHA-3 作为现行族的名字。</p></li></ul>',7))])}const H=o(d,[["render",m]]);export{_ as __pageData,H as default};
